/* Date windows are view filters; underlying task dates are never changed. */
(()=>{'use strict';if(!document.body.classList.contains('shared-app'))return;
let mode='calendar',generation=0,from='',to='';const previous=renderProgram;
const day=86400000,iso=n=>new Date(n).toISOString().slice(0,10),parse=s=>Date.parse(s+'T12:00:00Z');
function controls(){return '<form id="programRange" class="range-controls"><label>از تاریخ<input type="date" name="from" aria-label="شروع بازه برنامه" value="'+from+'" required></label><label>تا تاریخ<input type="date" name="to" aria-label="پایان بازه برنامه" value="'+to+'" required></label><button class="primary">اعمال بازه</button><button type="button" id="clearProgramRange" class="secondary">نمای پیش‌فرض</button></form>'}
renderProgram=async function(){const token=++generation,pid=project?.id;await previous();if(token!==generation||scope!=='program'||project?.id!==pid||!pid||window.SAMANDIS_PERSONAL_MODE)return;const root=el('#sharedContent');
try{const milestones=mode==='gantt'||from?await checked(db.from('sm_milestones').select('*').eq('project_id',pid).order('due')):[];if(token!==generation||scope!=='program'||project?.id!==pid)return;
const rows=[...tasks.filter(t=>t.due).map(t=>({id:t.id,title:t.title,start:(t.starts_on||t.created_at||t.due).slice(0,10),due:t.due,status:labels[t.status],done:t.status==='done'})),...milestones.map(m=>({id:m.id,title:m.title,start:m.starts_on||m.due,due:m.due,status:'موعد تحویل',delivery:true}))];
if(mode==='gantt'){const dates=rows.flatMap(r=>[r.start,r.due]).sort(),lo=from?parse(from):parse(dates[0]||iso(Date.now()))-day,hi=to?parse(to)+day:parse(dates.at(-1)||iso(Date.now()))+day,span=Math.max(day,hi-lo),pos=s=>(parse(s)-lo)/span*100;const visible=rows.filter(r=>parse(r.due)>=lo&&parse(r.start)<hi);const today=(Date.now()-lo)/span*100;
root.innerHTML='<section class="panel"><div class="panel-header"><h2>گانت پروژه</h2><small>بازهٔ کار: تاریخ شروع یا تعریف تا مهلت · زرد: تحویل · خط عمودی: امروز</small></div><div class="timeline-shell"><div class="timeline"><div class="time-header"><div class="time-label">کار و بازهٔ زمانی</div><div class="time-scale">'+Array.from({length:6},(_,i)=>'<span>'+date(iso(lo+(span-day)*i/5))+'</span>').join('')+'</div></div>'+visible.map(r=>{const a=Math.max(0,Math.min(100,pos(r.start))),b=Math.max(a,Math.min(100,pos(r.due)+day/span*100));return '<div class="time-row"><div class="time-label"><button class="task-title" data-plan-task="'+esc(r.id)+'" '+(r.delivery?'disabled':'')+'>'+esc(r.title)+'</button><small>'+date(r.start)+' تا '+date(r.due)+'</small></div><div class="time-track">'+(today>=0&&today<=100?'<i class="today-line" style="right:'+today+'%"></i>':'')+'<button class="time-bar '+(r.delivery?'delivery':'')+' '+(r.done?'completed':'')+'" style="right:'+a+'%;width:'+(b-a)+'%" data-plan-task="'+esc(r.id)+'" '+(r.delivery?'disabled':'')+' title="'+esc(r.title)+'">'+esc(r.status)+'</button></div></div>'}).join('')+(visible.length?'':'<div class="shared-empty">کاری در این بازه نیست.</div>')+'</div></div></section><p class="shared-meta">'+fa(tasks.filter(t=>!t.due).length)+' کار بدون مهلت در گانت نمایش داده نمی‌شود.</p>';
}else if(from&&to){const lo=parse(from),hi=parse(to),offset=(new Date(lo).getUTCDay()+1)%7;let cells=Array(offset).fill('<div class="calendar-cell blank"></div>').join('');for(let n=lo;n<=hi;n+=day){const key=iso(n);cells+='<div class="calendar-cell"><span class="day-number">'+date(key)+'</span>'+rows.filter(r=>r.due===key).map(r=>'<button class="cal-event '+(r.delivery?'delivery':'')+'" data-plan-task="'+esc(r.id)+'" '+(r.delivery?'disabled':'')+'>'+esc(r.title)+'</button>').join('')+'</div>'}root.innerHTML='<section class="panel"><div class="panel-header"><h2>تقویم بازهٔ انتخابی</h2><small>نمایش موعد تحویل کارها و تحویل‌های پروژه</small></div><div class="calendar-panel"><div class="calendar-grid">'+['شنبه','یکشنبه','دوشنبه','سه‌شنبه','چهارشنبه','پنجشنبه','جمعه'].map(d=>'<div class="weekday">'+d+'</div>').join('')+cells+'</div></div></section>'}
root.insertAdjacentHTML('afterbegin','<div class="program-switch" role="group" aria-label="نمای برنامه"><button data-program-mode="calendar" class="'+(mode==='calendar'?'active':'')+'">تقویم</button><button data-program-mode="gantt" class="'+(mode==='gantt'?'active':'')+'">گانت و تایملاین</button></div>'+controls());root.querySelectorAll('[data-program-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.programMode;renderProgram()});root.querySelectorAll('[data-plan-task]:not(:disabled)').forEach(b=>b.onclick=()=>detail(b.dataset.planTask));el('#programRange').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),a=f.get('from'),b=f.get('to');if(!a||!b||a>b)return message('تاریخ شروع باید قبل از پایان باشد.');if((parse(b)-parse(a))/day>365)return message('بازه را حداکثر یک سال انتخاب کنید.');from=a;to=b;renderProgram()};el('#clearProgramRange').onclick=()=>{from=to='';renderProgram()};
}catch(e){if(token===generation)message(failure(e))}};
})();
